def sum_open_hours(rows):
    """
    Suma las horas abiertas para cada responsable, considerando solo filas con estado 'open' o 'in_progress'.
    Ignora entradas inválidas y ordena el resultado alfabéticamente por nombre.
    """
    total = {}
    for row in rows:
        owner = row['owner']
        hours = row['hours']
        status = row['status'].lower()
        if status in ('open', 'in_progress'):
            total[owner] = sum(1 for h in hours if isinstance(h, (int, float)) and h >= 0)
    return dict(sorted(total.items(), key=lambda x: x[0]))
