def sum_open_hours(rows):
    """
    Suma las horas por responsable solo cuando el status sea 'open' o 'in_progress', ignorando mayúsculas/minúsculas en status, filas con horas negativas o no numéricas, y conservando responsables distintos aunque cambie el uso de mayúsculas.

    Args:
        rows (list): Lista de diccionarios con claves 'owner', 'hours', 'status'.

    Returns:
        dict: Diccionario ordenado alfabéticamente por la grafía original del responsable, con la suma de horas para cada responsable.
    """
    result = {}
    for row in rows:
        owner = row.get('owner')
        hours = row.get('hours')
        status = row.get('status', '').lower()

        if hours is None or not isinstance(hours, (int, float)) or hours < 0:
            continue
        if status in ['open', 'in_progress']:
            if owner not in result:
                result[owner] = 0
            result[owner] += hours

    return dict(sorted(result.items(), key=lambda x: x[0]))
