def sum_open_hours(rows):
    """
    Suma las horas por responsable solo cuando el status sea 'open' o 'in_progress',
    ignorando mayúsculas/minúsculas en status, ignorando filas con horas negativas o no numéricas,
    conservando responsables distintos aunque cambie el uso de mayúsculas y devuelve un diccionario
    ordenado alfabéticamente por la grafía original del responsable.
    """
    from collections import OrderedDict
    from itertools import groupby
    import re

    def is_valid_row(row):
        return row['status'].lower() in ['open', 'in_progress'] and re.match(r'^\d*\.?\d*$', str(row['hours']))

    def parse_hours(row):
        return float(row['hours'])

    valid_rows = [row for row in rows if is_valid_row(row)]
    valid_rows.sort(key=lambda x: x['owner'])

    result = OrderedDict()
    for owner, group in groupby(valid_rows, key=lambda x: x['owner']):
        hours = sum(parse_hours(row) for row in group)
        result[owner] = hours

    return OrderedDict(sorted(result.items()))
